'use strict';
const rooms=[{name:'Kitchen',src:'./assets/kitchen.jpg',alt:'Contemporary kitchen with natural wood and stone finishes'},{name:'Living room',src:'./assets/living.jpg',alt:'Open-plan living room with a bright balcony'},{name:'Dining',src:'./assets/dining.jpg',alt:'Dining space with architectural wood finishes'},{name:'Bedroom',src:'./assets/bedroom.jpg',alt:'Comfortable bedroom with soft furnishings'},{name:'Lounge',src:'./assets/lounge.jpg',alt:'A quiet residential lounge'},{name:'Bathroom',src:'./assets/bathroom.jpg',alt:'Bathroom with refined stone finishes'},{name:'Evening lounge',src:'./assets/living-evening.jpg',alt:'Living room at dusk with a sectional sofa, warm lighting and balcony doors'}];
const properties=[{id:'jacaranda',name:'The Jacaranda',area:'Kilimani',price:65000,size:112,beds:2,baths:2,room:0,description:'Warm wood. Quiet light. Room to breathe.\nA thoughtfully imagined city home, where\nthe everyday feels a little more considered.'},{id:'olive',name:'Olive',area:'Westlands',price:85000,size:128,beds:2,baths:2,room:1,description:'Room for connection. Space to slow down.\nAn imagined city retreat with open interiors\nand a softer rhythm to come home to.'},{id:'cedar',name:'The Cedar',area:'Lavington',price:95000,size:156,beds:3,baths:2,room:2,description:'A little more space for your next chapter.\nNatural textures and generous proportions,\nimagined around the way you live.'}];
const $=id=>document.getElementById(id);const icon=name=>`<svg aria-hidden="true"><use href="#${name}"/></svg>`;
let propertyIndex=0,roomIndex=0,saved=[],photoTimer,toastTimer;
try{const v=JSON.parse(localStorage.getItem('huna-gallery-shortlist')||'[]');if(Array.isArray(v))saved=v.filter(x=>properties.some(p=>p.id===x));}catch{}
function notify(text){$('toast').querySelector('span').textContent=text;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,3500)}
function saveState(){try{localStorage.setItem('huna-gallery-shortlist',JSON.stringify(saved));}catch{notify('Your browser could not save this shortlist.')}renderSave()}
function renderSave(){const active=saved.includes(properties[propertyIndex].id);$('save-property').classList.toggle('saved',active);$('save-property').setAttribute('aria-pressed',String(active));$('save-property').querySelector('span').textContent=active?'Saved':'Save';$('saved-count').textContent=saved.length;$('save-property').setAttribute('aria-label',active?'Remove this residence from shortlist':'Save this residence')}
function selectPhoto(index,focusThumb=false){roomIndex=(index+rooms.length)%rooms.length;const room=rooms[roomIndex],image=$('hero-photo');clearTimeout(photoTimer);image.classList.add('switching');photoTimer=setTimeout(()=>{image.src=room.src;image.alt=room.alt;image.onload=()=>image.classList.remove('switching');if(image.complete)image.classList.remove('switching')},130);$('image-count').textContent=String(roomIndex+1).padStart(2,'0')+' / '+String(rooms.length).padStart(2,'0');$('image-label').textContent='THE '+room.name.toUpperCase();document.querySelectorAll('.thumbnail').forEach((btn,i)=>{btn.classList.toggle('active',i===roomIndex);btn.setAttribute('aria-pressed',String(i===roomIndex));if(i===roomIndex&&focusThumb)btn.scrollIntoView({behavior:'smooth',block:'nearest',inline:'center'})})}
rooms.forEach((room,i)=>{const b=document.createElement('button');b.className='thumbnail'+(i===0?' active':'');b.setAttribute('aria-label','View '+room.name.toLowerCase());b.setAttribute('aria-pressed',String(i===0));b.innerHTML=`<img src="${room.src}" alt="" loading="${i<3?'eager':'lazy'}"><small>${String(i+1).padStart(2,'0')}</small><span>${room.name}</span>`;b.addEventListener('click',()=>selectPhoto(i));$('thumbnails').append(b)});
function selectProperty(index){propertyIndex=(index+properties.length)%properties.length;const p=properties[propertyIndex];$('property-title').innerHTML=p.name+'<br><em>Residence.</em>';$('location').textContent=p.area.toUpperCase()+', NAIROBI';$('neighbourhood').textContent=p.area;$('area').textContent=p.size+' m²';$('bedrooms').textContent=p.beds+' bedrooms';$('bathrooms').textContent=p.baths+' bathrooms';$('price').textContent='KES '+p.price.toLocaleString('en-KE');$('property-description').textContent=p.description;$('property-description').style.whiteSpace='pre-line';$('switcher-title').textContent=p.name;$('property-position').textContent=String(propertyIndex+1).padStart(2,'0');$('viewing-property').textContent=p.name;selectPhoto(p.room);renderSave();document.querySelectorAll('dialog[open]').forEach(d=>d.close())}
function propertyCards(target,filter){const list=$(target);list.replaceChildren();properties.forEach((p,i)=>{if(filter&&!saved.includes(p.id))return;const b=document.createElement('button');b.className='collection-card';b.innerHTML=`<img src="${rooms[p.room].src}" alt="Illustrative interior"><div><small>${p.area.toUpperCase()} · ${p.beds} BEDROOMS</small><h3>${p.name}</h3><p>KES ${p.price.toLocaleString('en-KE')} / month · indicative</p></div>${icon('arrow')}`;b.addEventListener('click',()=>selectProperty(i));list.append(b)});if(!list.children.length){const p=document.createElement('p');p.className='empty-shortlist';p.textContent='A home worth coming back to. Tap Save on a residence and find it here.';list.append(p)}}
function openDialog(name){if(name==='collection')propertyCards('collection-list',false);if(name==='shortlist')propertyCards('shortlist-list',true);if(name==='viewing')$('viewing-property').textContent=properties[propertyIndex].name;$(name+'-dialog').showModal()}
document.querySelectorAll('[data-dialog]').forEach(b=>b.addEventListener('click',()=>openDialog(b.dataset.dialog)));
document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.dialog-close').addEventListener('click',()=>d.close());d.addEventListener('click',e=>{const r=d.getBoundingClientRect();if(e.target===d&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))d.close()})});
$('shortlist-open').onclick=()=>openDialog('shortlist');$('story-explore').onclick=()=>{$('story-dialog').close();openDialog('collection')};
$('save-property').onclick=()=>{const id=properties[propertyIndex].id;const added=!saved.includes(id);saved=added?[...saved,id]:saved.filter(x=>x!==id);saveState();notify(added?'Residence added to your shortlist.':'Residence removed from your shortlist.')};
$('prev-photo').onclick=()=>selectPhoto(roomIndex-1,true);$('next-photo').onclick=()=>selectPhoto(roomIndex+1,true);$('prev-property').onclick=()=>selectProperty(propertyIndex-1);$('next-property').onclick=()=>selectProperty(propertyIndex+1);
$('close-details').onclick=()=>{$('details-panel').hidden=true;$('show-details').hidden=false;$('show-details').focus()};$('show-details').onclick=()=>{$('details-panel').hidden=false;$('show-details').hidden=true;$('close-details').focus()};
function expandGallery(){const expanded=$('residence').classList.toggle('expanded');document.body.style.overflow=expanded?'hidden':'';$('fullscreen').setAttribute('aria-label',expanded?'Exit expanded gallery':'Expand gallery');$('fullscreen').setAttribute('aria-pressed',String(expanded));$('fullscreen').innerHTML=icon(expanded?'close':'expand')}
$('fullscreen').onclick=expandGallery;
document.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]')||['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName))return;if(e.key==='ArrowRight'){e.preventDefault();selectPhoto(roomIndex+1,true)}if(e.key==='ArrowLeft'){e.preventDefault();selectPhoto(roomIndex-1,true)}if(e.key==='Escape'&&$('residence').classList.contains('expanded'))expandGallery()});
const dateInput=$('viewing-form').elements.date;const now=new Date();const today=new Date(now.getTime()-now.getTimezoneOffset()*60000).toISOString().slice(0,10);dateInput.min=today;
$('viewing-form').onsubmit=e=>{e.preventDefault();if(!$('viewing-form').reportValidity())return;const f=new FormData(e.currentTarget),p=properties[propertyIndex];if(String(f.get('date'))<today){notify('Choose today or a future date.');return}const brief=`HUNA FOR HUNA — VIEWING BRIEF\n\nDEMO PLANNER — NOT A CONFIRMED APPOINTMENT\nNo request has been sent to an agent.\n\nResidence: ${p.name}\nNeighbourhood: ${p.area}, Nairobi\nIndicative monthly rent: KES ${p.price.toLocaleString('en-KE')}\n\nName: ${f.get('name')}\nEmail: ${f.get('email')}\nPreferred date: ${f.get('date')}\nPreferred time: ${f.get('time')} (Nairobi)\n\nNotes:\n${f.get('notes')||'None'}\n\nAll property information and photography are illustrative. Availability, features, and rent must be verified before booking.\n`;const url=URL.createObjectURL(new Blob([brief],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='Huna-'+p.id+'-viewing-brief.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('viewing-dialog').close();notify('Viewing brief downloaded. No appointment has been booked.')};
$('hero-photo').addEventListener('error',()=>{$('hero-photo').classList.remove('switching');notify('This photo could not be loaded. Please try another room.')});renderSave();
